// Roda no dia 1 do mês, mas fecha o mês que ACABOU DE TERMINAR — não
// o mês corrente que só começou. § 05: certificado só sai se as 4
// semanas do mês existirem e baterem 100%.
const agora = new Date();
agora.setDate(1); // evita virar mês errado por causa do dia
agora.setMonth(agora.getMonth() - 1);
return [{ json: { ano: agora.getFullYear(), mes: agora.getMonth() + 1 } }];

// A rota é idempotente (checagem prévia + unique(aluno_id, mes_referencia)
// no banco) — 'jaTinham' alto não é falha, é sinal de que rodar de novo
// não duplica nada.
const body = $json.body ?? {};
const { ano, mes, total, emitidos, jaTinham, naoElegiveis, detalhe } = body;

console.log(`[WF01] ${ano}-${String(mes).padStart(2, '0')}: total=${total} emitidos=${emitidos} já tinham=${jaTinham} não elegíveis=${naoElegiveis}`);

if (!ano || !mes) {
  throw new Error(`[WF01] resposta inesperada do job — status HTTP ${$json.statusCode}, corpo: ${JSON.stringify(body).slice(0, 300)}`);
}

return [{ json: { ano, mes, total, emitidos, jaTinham, naoElegiveis, detalhe } }];
